const q1 = $('Fetch Unanswered Questions').item.json.items || [];
const q2 = $('Fetch n8n Questions').item.json.items || [];
const all = [...q1, ...q2];
const unique = all.filter((q,i,arr) => arr.findIndex(x=>x.question_id===q.question_id)===i);
const processed = unique.slice(0,15).map(q => ({
  title: q.title,
  tags: q.tags,
  votes: q.score,
  answers: q.answer_count,
  views: q.view_count,
  link: q.link,
  is_answered: q.is_answered,
  created: new Date(q.creation_date*1000).toISOString().split('T')[0]
}));
return [{ json: { questions: processed, unanswered: processed.filter(q=>!q.is_answered).length } }];

